   background: var(--color-surface-soft);
   color: var(--color-text);
 }

 .button-small {
   min-height: 2.45rem;
   padding: 0.58rem 0.9rem;
 }

 .icon-button {
   border: 1px solid var(--color-border);
   background: transparent;
   color: var(--color-text);
   padding: 0.55rem 0.85rem;
 }

 .icon-button[aria-pressed="true"] {
   border-color: var(--color-accent);
   background: #3b2a13;
   color: var(--color-accent-strong);
 }

 .hero-card {
   display: flex;
   flex-direction: column;
   justify-content: end;
   min-height: 27rem;
   border-radius: var(--radius-large);
   padding: 2rem;
   background:
     linear-gradient(160deg, transparent 0 45%, #111827 46%),
     radial-gradient(circle at 62% 24%, #f0b35b 0 4rem, transparent 4.1rem),
     radial-gradient(circle at 30% 55%, #7dd3fc 0 5.5rem, transparent 5.6rem),
     var(--color-surface-raised);
 }

 .hero-card h2 {
   font-size: clamp(2rem, 4vw, 3rem);
 }

 .price-line {
   color: var(--color-muted-text);
 }

 .price-line span,
 .price {
   color: var(--color-text);
   font-size: 1.35rem;
   font-weight: 950;
 }

 .status-message {
   width: min(calc(100% - 2rem), var(--container));
   margin: 0 auto;
   color: var(--color-success);
   font-weight: 800;
 }

 .status-message:empty {
   display: none;
 }

 .section {
   padding: 4rem 0;
 }

 .section-header {
   display: flex;
   justify-content: space-between;
   gap: 1rem;
   align-items: end;
   margin-bottom: 1.5rem;
 }

 .section-link,
 .deal-timer {
   color: var(--color-muted-text);
   font-weight: 850;
 }

 .product-grid {
   display: grid;
   grid-template-columns: repeat(3, minmax(0, 1fr));
   gap: 1rem;
   margin: 0;
   padding: 0;
   list-style: none;
 }

 .product-card {
   display: flex;
   min-height: 100%;
   flex-direction: column;
   border-radius: var(--radius-medium);
   overflow: hidden;
 }

 .product-art {
   min-height: 13rem;
   border-bottom: 1px solid var(--color-border);
   background: var(--color-surface-soft);
 }

 .product-art-coat {
   background:
     linear-gradient(130deg, transparent 0 40%, #223555 41% 70%, transparent 71%),
     radial-gradient(circle at 50% 35%, #8da9ce 0 4rem, transparent 4.1rem),
     var(--color-surface-soft);
 }

 .product-art-bag {
   background:
     radial-gradient(ellipse at 52% 66%, #caa15f 0 5.2rem, transparent 5.3rem),
     linear-gradient(90deg, transparent 42%, #0b101a 43% 57%, transparent 58%),
     var(--color-surface-soft);
 }

 .product-art-lamp {
   background:
     radial-gradient(circle at 50% 38%, #ffd28a 0 4.5rem, transparent 4.6rem),
     linear-gradient(90deg, transparent 48%, #9ea8bd 49% 51%, transparent 52%),
     var(--color-surface-soft);
 }

 .product-info,
 .card-actions {
   padding: 1.25rem;
 }

 .product-info {
   flex: 1;
 }

 .product-info p:not(.category):not(.price),
 .deal-card p:not(.deal-label),
 .feature-story p:not(.category),
 .story-list p:not(.category),
 .site-footer p,
 .membership p {
   color: var(--color-muted-text);
 }

 .deals-grid {
   display: grid;
   grid-template-columns: 1fr 1.25fr 1fr;
   gap: 1rem;
 }

 .deal-card {
   border-radius: var(--radius-medium);
   padding: 1.5rem;
 }

 .deal-card-accent {
   background:
     radial-gradient(circle at top right, #46300d 0, transparent 16rem),
     linear-gradient(145deg, #242b3c, #141b2a);
 }

 .editorial-layout {
   display: grid;
   grid-template-columns: 1.4fr 0.8fr;
   gap: 1rem;
 }

 .feature-story {
   display: grid;
   grid-template-columns: 0.9fr 1fr;
   gap: 1.25rem;
   border-radius: var(--radius-medium);
   padding: 1rem;
 }

 .story-image {
   min-height: 20rem;
   border-radius: calc(var(--radius-medium) - 6px);
   background:
     linear-gradient(135deg, #0d1424 20%, transparent 21% 48%, #3c4b65 49%),
     radial-gradient(circle at 60% 40%, #f0b35b 0 4rem, transparent 4.1rem),
     var(--color-surface-soft);
 }

 .story-list {
   display: grid;
   gap: 1rem;
 }

 .story-list article {
   border-radius: var(--radius-medium);
   padding: 1.5rem;
 }

 .membership {
   display: grid;
   grid-template-columns: 0.9fr 1.1fr;
   gap: 2rem;
   align-items: center;
   border-radius: var(--radius-large);
   margin-bottom: 4rem;
   padding: clamp(1.5rem, 4vw, 3rem);
 }

 .signup-form label {
   display: block;
   margin-bottom: 0.45rem;
   color: var(--color-text);
   font-weight: 850;
 }

 .signup-form input {
   flex: 1 1 15rem;
   min-height: 3rem;
   border: 1px solid var(--color-border);
   border-radius: 999px;
   background: var(--color-bg);
   color: var(--color-text);
   padding: 0 1rem;
 }

 .signup-form input::placeholder {
   color: var(--color-subtle-text);
 }

 .site-footer {
   display: flex;
   justify-content: space-between;
   gap: 2rem;
   border-top: 1px solid var(--color-border);
   padding: 2rem 0 3rem;
 }

 @media (max-width: 860px) {
   body.nav-open {
     overflow: auto;
   }

   .nav-shell {
     grid-template-columns: auto auto;
   }

   .nav-toggle {
     display: inline-flex;
     justify-self: end;
   }

   .primary-nav {
     display: none;
     grid-column: 1 / -1;
     border: 1px solid var(--color-border);
     border-radius: var(--radius-medium);
     background: var(--color-surface);
     padding: 1rem;
   }

   .primary-nav.is-open {
     display: block;
   }

   .primary-nav ul,
   .site-footer,
   .site-footer ul {
     align-items: stretch;
     flex-direction: column;
   }

   .primary-nav a {
     display: block;
     padding: 0.75rem;
   }

   .cart-link {
     grid-column: 1 / -1;
     justify-self: start;
   }

   .hero,
   .product-grid,
   .deals-grid,
   .editorial-layout,
   .feature-story,
   .membership {
     grid-template-columns: 1fr;
   }

   .hero {
     padding-top: 2rem;
   }

   .section-header {
     align-items: start;
     flex-direction: column;
   }
 }

 @media (max-width: 520px) {
   .announcement,
   .hero-actions,
   .card-actions,
   .signup-row {
     align-items: stretch;
     flex-direction: column;
   }

   .announcement {
     text-align: center;
   }

   .button,
   .icon-button {
     width: 100%;
   }

   .hero-card {
     min-height: 20rem;
   }
 }

 @media (prefers-reduced-motion: reduce) {
   *,
   *::before,
   *::after {
     scroll-behavior: auto !important;
     transition-duration: 0.01ms !important;
     animation-duration: 0.01ms !important;
     animation-iteration-count: 1 !important;
   }
 }

 @media (forced-colors: active) {
   .announcement,
   .button,
   .icon-button,
   .cart-link,
   .brand-mark,
   .product-card,
   .deal-card,
   .feature-story,
   .story-list article,
   .membership,
   .hero-copy,
   .hero-card {
     border: 2px solid ButtonBorder;
     box-shadow: none;
   }

   .button-primary,
   .announcement,
   .brand-mark,
   .cart-count {
     background: ButtonFace;
     color: ButtonText;
   }
 }

')

