      --shadow-raised: 0 20px 60px #000000;
      --radius-large: 28px;
      --radius-medium: 18px;
      --radius-small: 12px;
      --container: 1180px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      background:
        radial-gradient(circle at top left, #17294c 0, transparent 34rem),
        radial-gradient(circle at 80% 5%, #3a2447 0, transparent 28rem),
        var(--color-bg);
      color: var(--color-text);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.6;
    }

    body.nav-open {
      overflow: hidden;
    }

    a {
      color: inherit;
    }

    a:hover {
      color: var(--color-link);
    }

    a:focus-visible,
    button:focus-visible,
    input:focus-visible,
    main:focus-visible {
      outline: 3px solid var(--color-focus);
      outline-offset: 4px;
    }

    img,
    svg {
      max-width: 100%;
    }

    button,
    input {
      font: inherit;
    }

    button {
      cursor: pointer;
    }

    .skip-link {
      position: absolute;
      top: 1rem;
      left: 1rem;
      z-index: 20;
      transform: translateY(-150%);
      border-radius: var(--radius-small);
      background: var(--color-text);
      color: var(--color-bg);
      font-weight: 800;
      padding: 0.75rem 1rem;
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 10;
      border-bottom: 1px solid var(--color-border);
      background: var(--color-bg);
    }

    .announcement {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 1rem;
      padding: 0.55rem 1rem;
      background: var(--color-accent);
      color: #1c1205;
      font-weight: 800;
    }

    .announcement p {
      margin: 0;
    }

    .text-button {
      border: 0;
      border-bottom: 2px solid currentColor;
      background: transparent;
      color: inherit;
      font-weight: 800;
      padding: 0.1rem 0;
    }

    .nav-shell,
    .hero,
    .section,
    .membership,
    .site-footer {
      width: min(calc(100% - 2rem), var(--container));
      margin-inline: auto;
    }

    .nav-shell {
      display: grid;
      grid-template-columns: auto 1fr auto;
      align-items: center;
      gap: 1.5rem;
      padding: 1rem 0;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.7rem;
      text-decoration: none;
      font-size: 1.05rem;
      font-weight: 900;
      letter-spacing: 0.02em;
    }

    .brand-mark {
      display: inline-grid;
      width: 2.4rem;
      height: 2.4rem;
      place-items: center;
      border: 1px solid var(--color-accent);
      border-radius: 50%;
      background: var(--color-accent);
      color: #171006;
      box-shadow: 0 0 0 5px #3b2a13;
    }

    .primary-nav ul,
    .site-footer ul {
      display: flex;
      align-items: center;
      gap: 1.25rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .primary-nav a,
    .site-footer a {
      color: var(--color-muted-text);
      font-weight: 750;
      text-decoration: none;
    }

    .primary-nav a:hover,
    .site-footer a:hover {
      color: var(--color-text);
    }

    .nav-toggle {
      display: none;
      align-items: center;
      gap: 0.6rem;
      border: 1px solid var(--color-border);
      border-radius: 999px;
      background: var(--color-surface);
      color: var(--color-text);
      padding: 0.65rem 0.95rem;
    }

    .nav-toggle-icon,
    .nav-toggle-icon::before,
    .nav-toggle-icon::after {
      display: block;
      width: 1.1rem;
      height: 2px;
      border-radius: 999px;
      background: currentColor;
    }

    .nav-toggle-icon {
      position: relative;
    }

    .nav-toggle-icon::before,
    .nav-toggle-icon::after {
      content: "";
      position: absolute;
      left: 0;
    }

    .nav-toggle-icon::before {
      top: -0.38rem;
    }

    .nav-toggle-icon::after {
      top: 0.38rem;
    }

    .cart-link {
      justify-self: end;
      border: 1px solid var(--color-border);
      border-radius: 999px;
      color: var(--color-text);
      font-weight: 850;
      text-decoration: none;
      padding: 0.65rem 0.95rem;
    }

    .cart-count {
      display: inline-grid;
      min-width: 1.55rem;
      min-height: 1.55rem;
      margin-left: 0.35rem;
      place-items: center;
      border-radius: 50%;
      background: var(--color-accent);
      color: #171006;
    }

    .hero {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(18rem, 0.55fr);
      gap: 2rem;
      align-items: stretch;
      padding: 5rem 0 3rem;
    }

    .hero-copy,
    .hero-card,
    .product-card,
    .deal-card,
    .feature-story,
    .story-list article,
    .membership {
      border: 1px solid var(--color-border);
      background: linear-gradient(145deg, var(--color-surface-raised), var(--color-surface));
      box-shadow: var(--shadow-raised);
    }

    .hero-copy {
      border-radius: var(--radius-large);
      padding: clamp(2rem, 6vw, 4.5rem);
    }

    .eyebrow,
    .category,
    .deal-label {
      margin: 0 0 0.6rem;
      color: var(--color-accent-strong);
      font-size: 0.78rem;
      font-weight: 900;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    h1,
    h2,
    h3,
    p {
      overflow-wrap: break-word;
    }

    h1,
    h2,
    h3 {
      margin-top: 0;
      line-height: 1.05;
    }

    h1 {
      max-width: 11ch;
      margin-bottom: 1.2rem;
      font-size: clamp(3rem, 9vw, 6.75rem);
      letter-spacing: -0.08em;
    }

    h2 {
      margin-bottom: 0;
      font-size: clamp(2rem, 4vw, 3.5rem);
      letter-spacing: -0.05em;
    }

    h3 {
      margin-bottom: 0.75rem;
      font-size: clamp(1.25rem, 2vw, 1.7rem);
    }

    h3 a {
      text-decoration-thickness: 0.08em;
      text-underline-offset: 0.18em;
    }

    .hero-text {
      max-width: 42rem;
      color: var(--color-muted-text);
      font-size: 1.2rem;
    }

    .hero-actions,
    .card-actions,
    .signup-row {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
    }

    .button,
    .icon-button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 2.75rem;
      border-radius: 999px;
      font-weight: 900;
      text-decoration: none;
    }

    .button {
      border: 1px solid var(--color-border);
      padding: 0.78rem 1.15rem;
    }

    .button-primary {
      border-color: var(--color-accent);
      background: var(--color-accent);
      color: #171006;
    }

    .button-secondary,
    .button-small {
      background: var(--color-surface-soft);
      color: var(--color-text);
    }

    .button-small {
      min-height: 2.45rem;
      padding: 0.58rem 0.9rem;
    }

    .icon-button {
      border: 1px solid var(--color-border);
      background: transparent;
      color: var(--color-text);
      padding: 0.55rem 0.85rem;
    }

    .icon-button[aria-pressed="true"] {
      border-color: var(--color-accent);
      background: #3b2a13;
      color: var(--color-accent-strong);
    }

    .hero-card {
      display: flex;
      flex-direction: column;
      justify-content: end;
      min-height: 27rem;
      border-radius: var(--radius-large);
      padding: 2rem;
      background:
        linear-gradient(160deg, transparent 0 45%, #111827 46%),
        radial-gradient(circle at 62% 24%, #f0b35b 0 4rem, transparent 4.1rem),
        radial-gradient(circle at 30% 55%, #7dd3fc 0 5.5rem, transparent 5.6rem),
        var(--color-surface-raised);
    }

    .hero-card h2 {
      font-size: clamp(2rem, 4vw, 3rem);
    }

    .price-line {
      color: var(--color-muted-text);
    }

    .price-line span,
    .price {
      color: var(--color-text);
      font-size: 1.35rem;
      font-weight: 950;
    }

    .status-message {
      width: min(calc(100% - 2rem), var(--container));
      margin: 0 auto;
      color: var(--color-success);
      font-weight: 800;
    }

    .section {
      padding: 4rem 0;
    }

    .section-header {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: end;
      margin-bottom: 1.5rem;
    }

    .section-link,
    .deal-timer {
      color: var(--color-muted-text);
      font-weight: 850;
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .product-card {
      display: flex;
      min-height: 100%;
      flex-direction: column;
      border-radius: var(--radius-medium);
      overflow: hidden;
    }

    .product-art {
      min-height: 13rem;
      border-bottom: 1px solid var(--color-border);
      background: var(--color-surface-soft);
    }

    .product-art-coat {
      background:
        linear-gradient(130deg, transparent 0 40%, #223555 41% 70%, transparent 71%),
        radial-gradient(circle at 50% 35%, #8da9ce 0 4rem, transparent 4.1rem),
        var(--color-surface-soft);
    }

    .product-art-bag {
      background:
        radial-gradient(ellipse at 52% 66%, #caa15f 0 5.2rem, transparent 5.3rem),
        linear-gradient(90deg, transparent 42%, #0b101a 43% 57%, transparent 58%),
        var(--color-surface-soft);
    }

    .product-art-lamp {
      background:
        radial-gradient(circle at 50% 38%, #ffd28a 0 4.5rem, transparent 4.6rem),
        linear-gradient(90deg, transparent 48%, #9ea8bd 49% 51%, transparent 52%),
        var(--color-surface-soft);
    }

    .product-info,
    .card-actions {
      padding: 1.25rem;
    }

    .product-info {
      flex: 1;
    }

    .product-info p:not(.category):not(.price),
    .deal-card p:not(.deal-label),
    .feature-story p:not(.category),
    .story-list p:not(.category),
    .site-footer p,
    .membership p {
      color: var(--color-muted-text);
    }

    .deals-grid {
      display: grid;
      grid-template-columns: 1fr 1.25fr 1fr;
      gap: 1rem;
    }

    .deal-card {
      border-radius: var(--radius-medium);
      padding: 1.5rem;
    }

    .deal-card-accent {
      background:
        radial-gradient(circle at top right, #46300d 0, transparent 16rem),
        linear-gradient(145deg, #242b3c, #141b2a);
    }

    .editorial-layout {
      display: grid;
      grid-template-columns: 1.4fr 0.8fr;
      gap: 1rem;
    }

    .feature-story {
      display: grid;
      grid-template-columns: 0.9fr 1fr;
      gap: 1.25rem;
      border-radius: var(--radius-medium);
      padding: 1rem;
    }

    .story-image {
      min-height: 20rem;
      border-radius: calc(var(--radius-medium) - 6px);
      background:
        linear-gradient(135deg, #0d1424 20%, transparent 21% 48%, #3c4b65 49%),
        radial-gradient(circle at 60% 40%, #f0b35b 0 4rem, transparent 4.1rem),
        var(--color-surface-soft);
    }

    .story-list {
      display: grid;
      gap: 1rem;
    }

    .story-list article {
      border-radius: var(--radius-medium);
      padding: 1.5rem;
    }

    .membership {
      display: grid;
      grid-template-columns: 0.9fr 1.1fr;
      gap: 2rem;
      align-items: center;
      border-radius: var(--radius-large);
      margin-bottom: 4rem;
      padding: clamp(1.5rem, 4vw, 3rem);
    }

    .signup-form label {
      display: block;
      margin-bottom: 0.45rem;
      color: var(--color-text);
      font-weight: 850;
    }

    .signup-form input {
      flex: 1 1 15rem;
      min-height: 3rem;
      border: 1px solid var(--color-border);
      border-radius: 999px;
      background: var(--color-bg);
      color: var(--color-text);
      padding: 0 1rem;
    }

    .signup-form input[aria-invalid="true"] {
      border-color: var(--color-danger);
    }

    .signup-form input::placeholder {
      color: var(--color-subtle-text);
    }

    .required-marker,
    .form-error {
      color: var(--color-danger);
    }

    .form-error,
    .signup-form .status-message {
      min-height: 1.5em;
    }

    .site-footer {
      display: flex;
      justify-content: space-between;
      gap: 2rem;
      border-top: 1px solid var(--color-border);
      padding: 2rem 0 3rem;
    }

    @media (max-width: 860px) {
      body.nav-open {
        overflow: auto;
      }

      .nav-shell {
        grid-template-columns: auto auto;
      }

      .nav-toggle {
        display: inline-flex;
        justify-self: end;
      }

      .primary-nav {
        display: none;
        grid-column: 1 / -1;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-medium);
        background: var(--color-surface);
        padding: 1rem;
      }

      .primary-nav.is-open {
        display: block;
      }

      .primary-nav ul,
      .site-footer,
      .site-footer ul {
        align-items: stretch;
        flex-direction: column;
      }

      .primary-nav a {
        display: block;
        padding: 0.75rem;
      }

      .cart-link {
        grid-column: 1 / -1;
        justify-self: start;
      }

      .hero,
      .product-grid,
      .deals-grid,
      .editorial-layout,
      .feature-story,
      .membership {
        grid-template-columns: 1fr;
      }

      .hero {
        padding-top: 2rem;
      }

      .section-header {
        align-items: start;
        flex-direction: column;
      }
    }

    @media (max-width: 520px) {
      .announcement,
      .hero-actions,
      .card-actions,
      .signup-row {
        align-items: stretch;
        flex-direction: column;
      }

      .announcement {
        text-align: center;
      }

      .button,
      .icon-button {
        width: 100%;
      }

      .hero-card {
        min-height: 20rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      .announcement,
      .button,
      .icon-button,
      .cart-link,
      .brand-mark,
      .product-card,
      .deal-card,
      .feature-story,
      .story-list article,
      .membership,
      .hero-copy,
      .hero-card {
        border: 2px solid ButtonBorder;
        box-shadow: none;
      }

      .button-primary,
      .announcement,
      .brand-mark,
      .cart-count {
        background: ButtonFace;
        color: ButtonText;
      }
    }
  </style>
</head>
