      promo.hidden = true;
    });

    document.querySelectorAll("[data-product-name]").forEach((button) => {
      button.addEventListener("click", () => {
        const productName = button.dataset.productName;
        cartTotal += 1;
        cartCount.textContent = String(cartTotal);
        cartStatus.textContent = `${productName} added to cart. ${cartTotal} ${cartTotal === 1 ? "item" : "items"} in cart.`;
