      const seconds = (saleSeconds % 60).toString().padStart(2, "0");
      saleTimer.textContent = `${minutes}:${seconds}`;

      if (saleSeconds > 0) {
        saleSeconds -= 1;
        return;
      }

      saleTimer.textContent = "00:00";
    }

    function setEmailError(message) {
      emailError.textContent = message;
      emailInput.setAttribute("aria-invalid", message ? "true" : "false");
    }

    updateSaleTimer();
    window.setInterval(updateSaleTimer, 1000);

    emailInput.addEventListener("input", () => {
      if (emailInput.validity.valid) {
        setEmailError("");
      }
    });

    signupForm.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!emailInput.validity.valid) {
        const message = emailInput.validity.valueMissing
          ? "Error: Enter your email address."
          : "Error: Enter a valid email address like you@example.com.";
        setEmailError(message);
        signupStatus.textContent = "";
        emailInput.focus();
        return;
      }

      setEmailError("");
      signupStatus.textContent = "Thanks. Check your inbox to confirm your Northstar Circle membership.";
      signupForm.reset();
    });
