const { chromium } = require('/tmp/northstar-a11y/node_modules/playwright');
const axe = require('/tmp/northstar-a11y/node_modules/axe-core');
const path = require('path');
const pageUrl = `file://${path.resolve('index.html')}`;
const cases = [
  { name: 'desktop default', width: 1366, height: 900 },
  { name: 'narrow default', width: 320, height: 900 },
  { name: 'narrow nav open', width: 320, height: 900, action: async (page) => page.locator('.nav-toggle').click({ timeout: 5000 }) },
  { name: 'cart and saved state', width: 1366, height: 900, action: async (page) => { await page.locator('[data-product-name="Apex Storm Shell"]').click({ timeout: 5000 }); await page.locator('[data-save-button]').first().click({ timeout: 5000 }); } },
  { name: 'invalid signup state', width: 1366, height: 900, action: async (page) => page.locator('.signup-form button[type="submit"]').click({ timeout: 5000 }) }
];
(async () => {
  const browser = await chromium.launch();
  const summaries = [];
  for (const testCase of cases) {
    const page = await browser.newPage({ viewport: { width: testCase.width, height: testCase.height } });
    page.setDefaultTimeout(5000);
    await page.goto(pageUrl, { waitUntil: 'domcontentloaded' });
    if (testCase.action) await testCase.action(page);
    await page.addScriptTag({ content: axe.source });
    const result = await page.evaluate(async () => await window.axe.run());
    const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
    await page.close();
    const wcag = result.violations.filter((v) => !v.tags.includes('best-practice'));
    const bp = result.violations.filter((v) => v.tags.includes('best-practice'));
    summaries.push({
      case: testCase.name,
      horizontalOverflow: overflow,
      wcag: wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) })),
      bestPractice: bp.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))
    });
  }
  await browser.close();
  console.log(JSON.stringify(summaries, null, 2));
  process.exit(summaries.some((s) => s.wcag.length || s.horizontalOverflow) ? 1 : 0);
})().catch(async (error) => {
  console.error(error.message);
  process.exit(2);
});
