  <script>
    const navToggle = document.querySelector(".nav-toggle");
    const primaryNav = document.querySelector("#primary-navigation");
    const dismissPromoButton = document.querySelector("[data-dismiss-promo]");
    const promo = document.querySelector("#shipping-promo");
    const cartCount = document.querySelector("[data-cart-count]");
    const cartStatus = document.querySelector("[data-cart-status]");
    const saleTimer = document.querySelector("[data-sale-timer]");
    const signupForm = document.querySelector(".signup-form");
    const signupStatus = document.querySelector("[data-signup-status]");
    const emailInput = document.querySelector("#email");
    const emailError = document.querySelector("#email-error");

    let cartTotal = 0;
    let saleSeconds = 360;

    navToggle.addEventListener("click", () => {
      const isOpen = navToggle.getAttribute("aria-expanded") === "true";
      navToggle.setAttribute("aria-expanded", String(!isOpen));
      primaryNav.classList.toggle("is-open", !isOpen);
      document.body.classList.toggle("nav-open", !isOpen);
    });

    primaryNav.addEventListener("click", (event) => {
      if (event.target instanceof HTMLAnchorElement) {
        navToggle.setAttribute("aria-expanded", "false");
        primaryNav.classList.remove("is-open");
        document.body.classList.remove("nav-open");
      }
    });

    dismissPromoButton.addEventListener("click", () => {
      promo.hidden = true;
    });

    document.querySelectorAll("[data-product-name]").forEach((button) => {
      button.addEventListener("click", () => {
        const productName = button.dataset.productName;
        cartTotal += 1;
        cartCount.textContent = String(cartTotal);
        cartStatus.textContent = `${productName} added to cart. ${cartTotal} ${cartTotal === 1 ? "item" : "items"} in cart.`;
      });
    });

    document.querySelectorAll("[data-save-button]").forEach((button) => {
      button.addEventListener("click", () => {
        const isPressed = button.getAttribute("aria-pressed") === "true";
        button.setAttribute("aria-pressed", String(!isPressed));
        button.textContent = isPressed ? "Save" : "Saved";
      });
    });

    function updateSaleTimer() {
      const minutes = Math.floor(saleSeconds / 60).toString().padStart(2, "0");
      const seconds = (saleSeconds % 60).toString().padStart(2, "0");
      saleTimer.textContent = `${minutes}:${seconds}`;

      if (saleSeconds > 0) {
        saleSeconds -= 1;
        return;
      }

      saleTimer.textContent = "00:00";
    }

    function setEmailError(message) {
      emailError.textContent = message;
      emailInput.setAttribute("aria-invalid", message ? "true" : "false");
    }

    updateSaleTimer();
    window.setInterval(updateSaleTimer, 1000);

    emailInput.addEventListener("input", () => {
      if (emailInput.validity.valid) {
        setEmailError("");
      }
    });

    signupForm.addEventListener("submit", (event) => {
      event.preventDefault();

      if (!emailInput.validity.valid) {
        const message = emailInput.validity.valueMissing
          ? "Error: Enter your email address."
          : "Error: Enter a valid email address like you@example.com.";
        setEmailError(message);
        signupStatus.textContent = "";
        emailInput.focus();
        return;
      }

      setEmailError("");
      signupStatus.textContent = "Thanks. Check your inbox to confirm your Northstar Circle membership.";
      signupForm.reset();
    });
  </script>
